 1  #define BLKNUM 4
 2  /* 基本視聴料金，0は契約なしの場合 */
 3  const int basic_charge[] = {0, 3000, 5000},
 4            channel_block[BLKNUM] = {1, 3, 6, 10},
 5            channel_charge[2][BLKNUM] = {{1500, 1000, 700, 500},
 6                                        {1000, 800, 600, 400}};
